INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'boundary', 'n.', '/ˈbaʊndri/', '边界;界限;分界线', 'No new buildings are allowed within the park boundaries.', '公园边界内不允许新建任何建筑。', 'Fascinating Parks', 1, 0, 'senior', 'wordlist', 'elective1', 'U3', 'park boundaries', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'bush', 'n.', '/bʊʃ/', '灌木;矮树丛', 'Trees and bushes grow along the riversides in the park.', '公园里河岸边长满了树木和灌木。', 'Fascinating Parks', 2, 0, 'senior', 'wordlist', 'elective1', 'U3', 'trees and bushes', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'vast', 'adj.', '/vɑːst/', '辽阔的;巨大的;庞大的', 'Sarek is a vast park with no roads or towns.', '萨雷克是一座没有道路和城镇的辽阔公园。', 'Fascinating Parks', 3, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a vast park', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'valley', 'n.', '/ˈvæli/', '山谷;溪谷;流域', 'The Rapa River flows through the valley below the mountains.', '拉帕河流经群山下方的山谷。', 'Fascinating Parks', 4, 0, 'senior', 'wordlist', 'elective1', 'U3', 'down the valley', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'edge', 'n.', '/edʒ/', '边缘;边;边线;刀刃', 'I walked over to the mountain edge to watch the river.', '我走到山边去看那条河。', 'Fascinating Parks', 5, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the mountain edge', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'remote', 'adj.', '/rɪˈməʊt/', '偏远的;遥远的;关系疏远的', 'The park lies in a remote part of northern Sweden.', '这座公园位于瑞典北部一处偏远地带。', 'Fascinating Parks', 6, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a remote area', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'glacier', 'n.', '/ˈɡlæsiə(r)/', '冰川', 'When the ice melted, it left behind about a hundred glaciers.', '冰雪融化后,留下了大约一百条冰川。', 'Fascinating Parks', 7, 0, 'senior', 'wordlist', 'elective1', 'U3', 'ancient glaciers', '美音 /ˈɡleɪʃər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'reindeer', 'n.', '/ˈreɪndɪə(r)/', '驯鹿', 'Every spring a few Sami still follow their reindeer into the valleys.', '每年春天,仍有少数萨米人跟着驯鹿走进山谷。', 'Fascinating Parks', 8, 0, 'senior', 'wordlist', 'elective1', 'U3', 'follow the reindeer', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'territory', 'n.', '/ˈterətri/', '领土;版图;领域;地盘', 'The Sami people made this northern territory their home.', '萨米人把这片北方的土地当作自己的家园。', 'Fascinating Parks', 9, 0, 'senior', 'wordlist', 'elective1', 'U3', 'their own territory', '美音 /ˈterətɔːri/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'visible', 'adj.', '/ˈvɪzəbl/', '看得见的;可见的;明显的', 'An ancient cottage is visible at the far side of the valley.', '在山谷的另一头,可以看见一座古老的小屋。', 'Fascinating Parks', 10, 0, 'senior', 'wordlist', 'elective1', 'U3', 'clearly visible', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'cottage', 'n.', '/ˈkɒtɪdʒ/', '小屋;村舍;小别墅', 'Some Sami still live in old cottages in the mountain valleys.', '一些萨米人仍住在山谷里的旧小屋中。', 'Fascinating Parks', 11, 0, 'senior', 'wordlist', 'elective1', 'U3', 'an old cottage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'stretch', 'v.', '/stretʃ/', '延伸;延续;伸展', 'The new park stretches all the way to the border with Russia.', '这座新公园一直延伸到与俄罗斯接壤的边境。', 'Fascinating Parks', 12, 0, 'senior', 'wordlist', 'elective1', 'U3', 'stretch to the border', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'rare', 'adj.', '/reə(r)/', '稀少的;珍贵的;罕见的', 'It is a rare chance to explore such a wild and quiet place.', '探索如此荒野而宁静的地方是一次难得的机会。', 'Fascinating Parks', 13, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a rare chance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'wander', 'v.', '/ˈwɒndə(r)/', '漫步;闲逛;游荡;走神', 'As you wander around the park, you may see deer feeding on grass.', '当你在公园里漫步时,可能会看到鹿在吃草。', 'Fascinating Parks', 14, 0, 'senior', 'wordlist', 'elective1', 'U3', 'wander around', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'route', 'n.', '/ruːt/', '路线;路途;途径', 'The guide drew the best route across the park on the map.', '向导在地图上画出了穿越公园的最佳路线。', 'Fascinating Parks', 15, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the best route', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'corridor', 'n.', '/ˈkɒrɪdɔː(r)/', '走廊;过道;通道;狭长地带', 'You can walk through an underwater corridor and watch the fish.', '你可以穿过一条水下走廊观赏鱼群。', 'Fascinating Parks', 16, 0, 'senior', 'wordlist', 'elective1', 'U3', 'an underwater corridor', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fountain', 'n.', '/ˈfaʊntən/', '喷泉;喷水池', 'In the evening we watched a beautiful fountain performance.', '傍晚我们观看了一场美丽的喷泉表演。', 'Fascinating Parks', 17, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a fountain performance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'pedal', 'n.', '/ˈpedl/', '踏板;脚镫子', 'We rented a pedal boat and rowed across the lake.', '我们租了一条脚踏船划过湖面。', 'Fascinating Parks', 18, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a pedal boat', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'enormous', 'adj.', '/ɪˈnɔːməs/', '巨大的;极大的', 'The park has rides from enormous swinging ships to free-fall drops.', '公园里既有巨大的摇摆船,也有自由落体跳楼机。', 'Fascinating Parks', 19, 0, 'senior', 'wordlist', 'elective1', 'U3', 'enormous ships', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'swing', 'v.', '/swɪŋ/', '(使)摆动;摇摆;转向', 'The giant ship swings back and forth high above the ground.', '那艘巨大的船在高空中前后摆动。', 'Fascinating Parks', 20, 0, 'senior', 'wordlist', 'elective1', 'U3', 'swing back and forth', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'incredible', 'adj.', '/ɪnˈkredəbl/', '难以置信的;极好的;极大的', 'There is an incredible theme park that will appeal to almost everyone.', '有一座令人难以置信的主题公园,几乎能吸引每个人。', 'Fascinating Parks', 21, 0, 'senior', 'wordlist', 'elective1', 'U3', 'an incredible park', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'splendid', 'adj.', '/ˈsplendɪd/', '壮丽的;雄伟的;极佳的', 'At night you can see the splendid parade and fireworks display.', '夜晚你可以观赏壮丽的游行和烟花表演。', 'Fascinating Parks', 22, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a splendid parade', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'superb', 'adj.', '/suːˈpɜːb/', '极佳的;卓越的', 'Dollywood has a superb wooden roller coaster called Thunderhead.', '多莉坞有一座极佳的木制过山车,名叫雷霆头。', 'Fascinating Parks', 23, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a superb roller coaster', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'entertainment', 'n.', '/ˌentəˈteɪnmənt/', '娱乐;招待;文娱活动', 'If it is ocean entertainment you want, come to this park.', '如果你想要海洋娱乐,就来这座公园吧。', 'Fascinating Parks', 24, 0, 'senior', 'wordlist', 'elective1', 'U3', 'ocean entertainment', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'theme', 'n.', '/θiːm/', '主题;主题思想', 'There are theme parks for almost everything, from food to history.', '几乎万物都有相应的主题公园,从美食到历史。', 'Fascinating Parks', 25, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a theme park', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'display', 'n.', '/dɪˈspleɪ/', '展览;陈列;表演;显示', 'The fireworks display lit up the whole night sky over the park.', '烟花表演照亮了公园上空的整个夜空。', 'Fascinating Parks', 26, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a fireworks display', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'iron', 'n.', '/ˈaɪən/', '铁;铁器;熨斗', 'Skilled workers make wood, glass, and iron objects in the old way.', '熟练工人用传统方式制作木器、玻璃器和铁器。', 'Fascinating Parks', 27, 0, 'senior', 'wordlist', 'elective1', 'U3', 'iron objects', '美音 /ˈaɪərn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'steam', 'n.', '/stiːm/', '蒸汽;水蒸气;蒸汽动力', 'Riding on the only working steam engine here is a special treat.', '乘坐这里唯一还在运行的蒸汽机车是一种特别的享受。', 'Fascinating Parks', 28, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a steam engine', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'leopard', 'n.', '/ˈlepəd/', '豹', 'The national park now protects about thirty-five tigers and seventy leopards.', '这座国家公园如今保护着约三十五只虎和七十只豹。', 'Fascinating Parks', 29, 0, 'senior', 'wordlist', 'elective1', 'U3', 'tigers and leopards', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'polar', 'adj.', '/ˈpəʊlə(r)/', '极地的;南极(或北极)的', 'At the ocean park you can even see real polar bears.', '在海洋公园你甚至能看到真正的北极熊。', 'Fascinating Parks', 30, 0, 'senior', 'wordlist', 'elective1', 'U3', 'polar bears', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'lung', 'n.', '/lʌŋ/', '肺', 'The wetland park is called the green lungs of the city.', '这座湿地公园被称为这座城市的绿肺。', 'Fascinating Parks', 31, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the green lungs', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'prohibit', 'v.', '/prəˈhɪbɪt/', '(尤指以法令)禁止;阻止', 'Park rules prohibit hunting and picking flowers inside the reserve.', '公园规定禁止在保护区内狩猎和采花。', 'Fascinating Parks', 32, 0, 'senior', 'wordlist', 'elective1', 'U3', 'prohibit hunting', '美音 /proʊˈhɪbɪt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'prohibition', 'n.', '/ˌprəʊɪˈbɪʃn/', '禁止;阻止;禁令', 'A prohibition on hunting helped the rare animals slowly increase.', '狩猎禁令帮助这些珍稀动物数量缓慢回升。', 'Fascinating Parks', 33, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a prohibition on hunting', '美音 /ˌproʊəˈbɪʃn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fashion', 'n.', '/ˈfæʃn/', '方式;时尚;流行款式', 'All the new buildings were designed in a traditional fashion.', '所有新建筑都以传统的方式设计。', 'Fascinating Parks', 34, 0, 'senior', 'wordlist', 'elective1', 'U3', 'in a traditional fashion', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'label', 'v.', '/ˈleɪbl/', '贴标签;用标签标明', 'He ordered the dish labelled "Pumpkin Pie and Ice Cream".', '他点了那道标着"南瓜派配冰激凌"的菜。', 'Fascinating Parks', 35, 0, 'senior', 'wordlist', 'elective1', 'U3', 'label the dish', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'journalist', 'n.', '/ˈdʒɜːnəlɪst/', '新闻记者;新闻工作者', 'A travel journalist wrote a long report about the hidden park.', '一位旅行记者写了一篇关于这座隐秘公园的长篇报道。', 'Fascinating Parks', 36, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a travel journalist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'column', 'n.', '/ˈkɒləm/', '(报刊的)专栏;栏;柱(形物)', 'She writes a weekly travel column about national parks.', '她每周写一个关于国家公园的旅行专栏。', 'Fascinating Parks', 37, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a travel column', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'sneeze', 'v.', '/sniːz/', '打喷嚏', 'The cold mountain air made me sneeze again and again.', '寒冷的山间空气让我一次又一次地打喷嚏。', 'Fascinating Parks', 38, 0, 'senior', 'wordlist', 'elective1', 'U3', 'sneeze in the cold', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'sour', 'adj.', '/ˈsaʊə(r)/', '酸的;有酸味的', 'I ate some sweet and sour berries growing near my tent.', '我吃了一些长在帐篷附近又甜又酸的浆果。', 'Fascinating Parks', 39, 0, 'senior', 'wordlist', 'elective1', 'U3', 'sweet and sour berries', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'cream', 'n.', '/kriːm/', '奶油;乳脂;护肤霜', 'The candy shop sells pie and ice cream made in the old way.', '那家糖果店出售用老办法制作的派和冰激凌。', 'Fascinating Parks', 40, 0, 'senior', 'wordlist', 'elective1', 'U3', 'ice cream', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'teapot', 'n.', '/ˈtiːpɒt/', '茶壶', 'He bought a traditional tea set with a nice teapot at the shop.', '他在店里买了一套带漂亮茶壶的传统茶具。', 'Fascinating Parks', 41, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a nice teapot', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'cloth', 'n.', '/klɒθ/', '布;织物;布料', 'I woke to the sound of the wind hitting the cloth of my tent.', '我被风拍打帐篷布的声音吵醒。', 'Fascinating Parks', 42, 0, 'senior', 'wordlist', 'elective1', 'U3', 'the cloth of a tent', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'bless', 'v.', '/bles/', '祝福;保佑;使有幸', 'Being in such a wild place makes me feel blessed to be alive.', '身处如此荒野之地,让我感到活着是一种幸福。', 'Fascinating Parks', 43, 0, 'senior', 'wordlist', 'elective1', 'U3', 'feel blessed', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'rewarding', 'adj.', '/rɪˈwɔːdɪŋ/', '值得做的;有益的', 'Hiking through the mountains was tiring but truly rewarding.', '徒步穿越群山虽然累,却真的很值得。', 'Fascinating Parks', 44, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a rewarding trip', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'pirate', 'n.', '/ˈpaɪrət/', '海盗;盗版者', 'At the water park you can join a water fight against pirates.', '在水上公园你可以加入一场对抗海盗的水仗。', 'Fascinating Parks', 45, 0, 'senior', 'wordlist', 'elective1', 'U3', 'fight against pirates', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'buffet', 'n.', '/ˈbʊfeɪ/', '自助餐', 'The park restaurant offers a buffet dinner with tasty local food.', '公园餐厅提供一顿有美味当地食物的自助晚餐。', 'Fascinating Parks', 46, 0, 'senior', 'wordlist', 'elective1', 'U3', 'a buffet dinner', '美音 /bəˈfeɪ/');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e1u3.01', '①that 引导主语从句(that 只起连接、不充当成分)', 'A2', 10, '选择性必修一 U3 — 从句结构完整、不缺主语或宾语,只需要一个不充当成分的连接词时,用 that。如 That he survived the storm is a miracle.', 1, 'elective1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e1u3.02', '②连接代词/副词引导主语从句(wh- 词在从句中充当成分)', 'A2', 10, '选择性必修一 U3 — 从句缺主语/宾语用 what/who;表''是否''用 whether(不用 if);表原因/方式用 why/how。该词在从句里充当成分。', 2, 'elective1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e1u3.03', '③it 作形式主语,真正的从句主语后置', 'A2', 10, '选择性必修一 U3 — 用 it 作形式主语、把从句移到句末:陈述事实 that;''谁''用 who;''是否''用 whether(句首 it 时不用 if)。', 3, 'elective1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ Sarek became a national park in 1909 is well known to visitors.', 'That', 'What', 'Whether', 'How', 'A', '从句 ''Sarek became a national park in 1909'' 结构完整、不缺主宾,只需连接词 → that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the Sami still follow their reindeer each spring surprises many tourists.', 'What', 'That', 'Whether', 'If', 'B', '从句完整(主谓宾齐全)→ 用不充当成分的 that;if 不引导主语从句。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ no roads cross the park makes it hard to reach.', 'What', 'Whether', 'That', 'How', 'C', '从句 ''no roads cross the park'' 完整 → that。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the ice melted thousands of years ago is shown by the glaciers left behind.', 'What', 'Whether', 'Why', 'That', 'D', '从句完整、陈述事实 → that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ all new building is banned inside the park protects its natural state.', 'That', 'What', 'Whether', 'If', 'A', '从句 ''all new building is banned…'' 完整 → that;if 不能引导主语从句。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the writer felt blessed in such a wild place is clear from the passage.', 'What', 'That', 'Whether', 'How', 'B', '从句完整、陈述事实 → that。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the park covers a vast area means animals have plenty of space.', 'What', 'Whether', 'That', 'Why', 'C', '从句完整 → 连接词 that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ Disneyland can be found in several parts of the world is true.', 'What', 'Whether', 'If', 'That', 'D', '从句完整 → that;不可用 if。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the Sami used reindeer for food, tools and clothes is part of their history.', 'That', 'What', 'Whether', 'How', 'A', '从句完整 → that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ a ban on hunting helped the tigers recover has been proved by the numbers.', 'What', 'That', 'Whether', 'Why', 'B', '从句 ''a ban on hunting helped…'' 完整 → that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the wetland produces clean water and oxygen is widely recognised.', 'What', 'Whether', 'That', 'If', 'C', '从句完整 → that;if 不引导主语从句。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the sun never sets there in summer makes the days feel endless.', 'What', 'Whether', 'How', 'That', 'D', '从句完整 → that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the new park is four times larger than the old one pleased the scientists.', 'That', 'What', 'Whether', 'Why', 'A', '从句完整 → that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ visitors must carry all their own food makes the hike harder.', 'What', 'That', 'Whether', 'If', 'B', '从句完整 → that;不用 if。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the park connects with Russia''s reserves gives the animals more room.', 'What', 'Whether', 'That', 'How', 'C', '从句完整 → that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the Sami are allowed to keep their traditional life is stated in the rules.', 'What', 'Whether', 'Why', 'That', 'D', '从句完整 → that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ Dollywood celebrates southeastern culture is clear to every visitor.', 'That', 'What', 'Whether', 'If', 'A', '从句完整 → that;不可用 if。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ trees grow right in the shallows makes the wetland special.', 'What', 'That', 'Whether', 'How', 'B', '从句完整 → that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the candy is made the same way as 150 years ago is a rare experience.', 'What', 'Whether', 'That', 'Why', 'C', '从句完整 → that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.01'), '____ the park stays natural and beautiful is what everyone hopes for.', 'What', 'Whether', 'If', 'That', 'D', '从句完整 → that;if 不引导主语从句。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ matters most in a national park is the protection of nature.', 'What', 'That', 'Whether', 'If', 'A', '从句缺主语(__ matters most)→ what 充当主语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ we visit Sarek or not depends on the weather and our supplies.', 'That', 'Whether', 'What', 'How', 'B', '表''是否''、主语从句句首 → whether(不用 if)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ designed the wetland park kept human impact to a minimum.', 'That', 'What', 'Whoever', 'Whether', 'C', '从句缺主语、指人''无论谁''→ whoever。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the Sami left the mountains is easy to understand once you know the cold.', 'That', 'What', 'If', 'Why', 'D', '表原因、从句缺原因状语 → why。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the park attracts so many tourists is its breathtaking beauty.', 'What', 'That', 'Whether', 'How', 'A', '从句缺主语(__ attracts…)→ what 作主语。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the reindeer survive the long winter amazes scientists every year.', 'That', 'How', 'What', 'If', 'B', '表方式''如何''、从句不缺主宾 → how。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the rangers find first will be marked on the map.', 'That', 'Whether', 'Whatever', 'How', 'C', '从句缺宾语(find __)、''无论什么''→ whatever。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the old park was too small worried the local scientists.', 'What', 'Whether', 'If', 'That', 'D', '从句完整、陈述事实 → that(此处对照:from句不缺成分则用 that)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the tigers go to hunt covers a very large area of forest.', 'Where', 'That', 'What', 'If', 'A', '表地点、从句缺地点状语 → where。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ we should develop a place like Sarek is still under discussion.', 'That', 'Whether', 'What', 'If', 'B', '表''是否''、句首主语从句 → whether,不用 if。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the Sami eat for breakfast often includes dried reindeer meat.', 'That', 'Whether', 'What', 'How', 'C', '从句缺宾语(eat __)→ what 作宾语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ first set up the reserve cared deeply about the rare animals.', 'That', 'What', 'Whether', 'Whoever', 'D', '从句缺主语、指人 → whoever。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the writer chose to camp alone shows his love of the wild.', 'Why', 'What', 'Whether', 'If', 'A', '表原因、从句不缺主宾 → why。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ makes Dollywood unique is its traditional southeastern culture.', 'That', 'What', 'Whether', 'How', 'B', '从句缺主语(__ makes…)→ what。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the park will open the new trail this year has not been decided.', 'That', 'What', 'Whether', 'If', 'C', '表''是否''、句首主语从句 → whether,不用 if。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the ice once covered these mountains can still be seen in the glaciers.', 'What', 'Whether', 'How', 'That', 'D', '从句完整、陈述事实 → that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the designers were most worried about was the impact on wildlife.', 'What', 'That', 'Whether', 'If', 'A', '从句缺宾语(worried about __)→ what。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the tigers'' numbers rose after 2015 is something the rules explain.', 'What', 'Why', 'Whether', 'If', 'B', '表原因、从句不缺主宾 → why。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ the wetland keeps so many birds and fish lies in its clean water.', 'What', 'Whether', 'Why', 'If', 'C', '表原因、从句完整 → why。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.02'), '____ you can do at the ocean park ranges from rides to dolphin shows.', 'That', 'Whether', 'How', 'What', 'D', '从句缺宾语(can do __)→ what。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is important ____ we protect parks for future generations.', 'that', 'what', 'whether', 'how', 'A', 'it 作形式主语、真正主语为完整从句、陈述事实 → that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It doesn''t matter ____ wins the design competition for the new park.', 'that', 'who', 'whether', 'if', 'B', '真正主语从句缺主语、指人 → who。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is still unknown ____ the new trail will open this summer.', 'that', 'what', 'whether', 'if', 'C', 'it 作形式主语、表''是否''→ whether(此处不用 if)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is a miracle ____ the rare tigers have come back at all.', 'what', 'whether', 'how', 'that', 'D', 'it 形式主语、陈述事实 → that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is not clear ____ banned the first hunting in the area.', 'who', 'that', 'whether', 'if', 'A', '真正主语从句缺主语、指人 → who。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It remains a question ____ such a wild place should be developed.', 'that', 'whether', 'what', 'if', 'B', '表''是否''、it 形式主语 → whether,不用 if。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is amazing ____ the sun never sets there during the summer months.', 'what', 'whether', 'that', 'who', 'C', 'it 形式主语、陈述事实 → that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is up to the rangers ____ marks the new route on the park map.', 'that', 'whether', 'if', 'who', 'D', '真正主语从句缺主语、指人 → who。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is doubtful ____ many more roads should be built near the reserve.', 'whether', 'that', 'what', 'if', 'A', '表''是否''、it 形式主语 → whether。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is true ____ the Sami have lived in this territory for centuries.', 'what', 'that', 'whether', 'how', 'B', 'it 形式主语、陈述事实 → that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is unclear ____ named the park after the nearby mountain.', 'that', 'whether', 'who', 'if', 'C', '真正主语从句缺主语、指人 → who。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is uncertain ____ the wetland can stay clean as the city grows.', 'that', 'what', 'if', 'whether', 'D', '表''是否''、it 形式主语 → whether,不用 if。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is well known ____ the park bans all new development inside its boundaries.', 'that', 'what', 'whether', 'who', 'A', 'it 形式主语、陈述事实 → that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It does not matter ____ first discovered the hidden valley.', 'that', 'who', 'whether', 'if', 'B', '真正主语从句缺主语、指人 → who。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is still being discussed ____ tourists should be allowed to camp here.', 'that', 'what', 'whether', 'if', 'C', '表''是否''、it 形式主语 → whether。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is clear ____ the writer thinks the hard hiking is worth it.', 'what', 'whether', 'how', 'that', 'D', 'it 形式主语、陈述事实 → that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is hard to say ____ designed the underwater corridor at the park.', 'who', 'that', 'whether', 'if', 'A', '真正主语从句缺主语、指人 → who。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is not yet decided ____ the park will host the fountain show again.', 'that', 'whether', 'what', 'if', 'B', '表''是否''、it 形式主语 → whether,不用 if。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is wonderful ____ children can ride and learn about nature at the park.', 'what', 'whether', 'that', 'who', 'C', 'it 形式主语、陈述事实 → that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective1' AND unit='U3' AND code='e1u3.03'), 'It is anyone''s guess ____ will win the prize at the park''s photo contest.', 'that', 'whether', 'if', 'who', 'D', '真正主语从句缺主语、指人 → who。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Summer Where the Sun Never Sleeps', 'I wake up to the sound of the wind hitting the cloth of my tent. Even though the sun is shining brightly, telling whether it is morning or night is impossible. I am above the Arctic Circle, where in summer the sun never sets. Checking my watch, I see that it is half past seven in the morning. I leave my tent and walk over to the mountain edge. Spreading out before me, branches of a river flow through the valley below. I am in the remote far north of Sweden, in a vast park with no roads and no towns. Getting here is quite difficult, so very few people have ever seen this place. To carry all my food and supplies, my bag weighs about thirty kilograms, and the hike over this difficult land is full of sweat and hard work. Yet being in such a beautiful and wild place makes me feel blessed to be alive.', '记叙·萨雷克国家公园', 158, '[{"q":"Why is it hard for the writer to tell the time of day?","answer":"A","options":["Because the sun does not set there in summer.","Because his watch has stopped working.","Because thick clouds cover the whole sky.","Because the tent has no windows at all."],"explanation":"原文 ''in summer the sun never sets'' 的转述。"},{"q":"What makes the writer''s journey so tiring?","answer":"B","options":["He has to swim across a wide river.","He must carry all his food and a heavy bag over hard land.","He gets lost on the way many times.","He has to build a new road as he walks."],"explanation":"原文 ''carry all my food… bag weighs about thirty kilograms… full of sweat and hard work'' 的转述。"},{"q":"How does the writer feel about being in this wild place?","answer":"A","options":["Lucky and grateful to be there.","Lonely and eager to leave.","Bored by the empty land.","Worried about the cold weather."],"explanation":"原文 ''makes me feel blessed to be alive'' 的转述(感到有幸)。"}]'::jsonb, '[{"word":"cloth","cn":"布料"},{"word":"remote","cn":"偏远的"},{"word":"vast","cn":"辽阔的"},{"word":"edge","cn":"边缘"},{"word":"blessed","cn":"有幸的"}]'::jsonb, 2, 'elective1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Sami and Their Reindeer', 'Long ago, the mountains here were covered by huge sheets of ice. About nine thousand years ago this ice melted, leaving behind around a hundred glaciers. Soon after, reindeer began to arrive, and following them came the Sami people, who made this northern territory their home. For hundreds of years, looking after reindeer was a way of life for the Sami. They used the animals'' meat for food, their bones for tools, and their skin for making clothes and tents. Because the reindeer were always on the move, the Sami would pick up their tents and travel with them. Today, most Sami have houses in villages and live a modern life, much like their neighbours. Yet every spring a small number of them still follow their reindeer into the valleys, living in tents or old cottages and enjoying their traditions. In 1909 the area became a national park, and now no one but the Sami may live inside it.', '说明·萨米人与驯鹿', 159, '[{"q":"What happened after the ice in the mountains melted?","answer":"B","options":["The whole area turned into desert.","Reindeer arrived, and the Sami followed them.","A large city was built in the valley.","All the rivers in the region dried up."],"explanation":"原文 ''reindeer began to arrive… following them came the Sami'' 的转述。"},{"q":"How did the Sami traditionally use their reindeer?","answer":"C","options":["Only to pull heavy carts of stone.","Mainly to guard their villages at night.","For food, tools, clothes and tents.","Just to sell them to foreign traders."],"explanation":"原文 ''meat for food, their bones for tools, and their skin for making clothes and tents'' 的概括。"},{"q":"What is the situation for most Sami people today?","answer":"D","options":["They have left the region forever.","They no longer keep any reindeer.","They are not allowed in the park.","They live a modern life in villages."],"explanation":"原文 ''most Sami have houses in villages and live a modern life'' 的转述。"}]'::jsonb, '[{"word":"glacier","cn":"冰川"},{"word":"reindeer","cn":"驯鹿"},{"word":"territory","cn":"领地"},{"word":"cottage","cn":"小屋"}]'::jsonb, 2, 'elective1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Home for Tigers and Leopards', 'In northeastern China, a huge new national park was set up to protect Siberian tigers and leopards. The park reaches all the way to the border and joins with wildlife reserves across it. It is nearly four times larger than the old park that once protected these animals. Over the years, growing development in the area had damaged the tigers'' homes, and by 1998 it was thought that only six to nine wild Siberian tigers were left in the region. Then, in 2015, a ban on development was put in place. Slowly the numbers began to rise, and the area is now thought to have about thirty-five tigers and seventy leopards. The problem with the old park had been its small size, for these large animals need wide spaces to hunt for food. With a connection to the reserves over the border, the new and far bigger park should give the rare cats the natural room they need to live and grow.', '说明·东北虎豹国家公园', 162, '[{"q":"Why were there so few wild Siberian tigers by 1998?","answer":"A","options":["Increasing development had damaged their habitat.","They had all moved across the border.","Hunters had been given new licences.","A long drought had dried up the forest."],"explanation":"原文 ''growing development… had damaged the tigers'' homes'' 的转述。"},{"q":"What change followed the ban on development in 2015?","answer":"B","options":["The tigers left the area completely.","Their numbers slowly started to increase.","The park was made much smaller.","The reserves across the border closed."],"explanation":"原文 ''… numbers began to rise… about thirty-five tigers and seventy leopards'' 的转述。"},{"q":"Why does the new park need to be so large?","answer":"C","options":["To make room for many new hotels.","To allow cars to drive freely inside.","Because large cats require broad areas in which to find their prey.","Because the old park had too many visitors."],"explanation":"原文 ''these large animals need wide spaces to hunt for food'' 的转述。"}]'::jsonb, '[{"word":"leopard","cn":"豹"},{"word":"ban","cn":"禁令"},{"word":"reserve","cn":"保护区"},{"word":"rare","cn":"稀少的"}]'::jsonb, 2, 'elective1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Green Lungs of the City', 'Covering about ten square kilometres in the west of Hangzhou, Xixi is the first national wetland park in China. The way it brings together city life, nature and wetlands makes it a favourite spot for both tourists and local people. At Xixi, taking a boat tour, walking along the paths, and learning about the customs of the old villages are among visitors'' best-loved activities. With trees, bushes and colourful flowers growing along the riversides, the park shows a different kind of beauty in each season. When the park was planned, the designers worked hard to limit the impact of people on the land. All the new buildings were made in a traditional fashion so that they would fit into the natural world around them. This green, watery place is home to many birds and fish. With trees growing right in the shallow water, the wetland works as a natural system that cleans water and produces oxygen, which is why people call it the green lungs of the city.', '说明·西溪国家湿地公园', 168, '[{"q":"What makes Xixi such a popular place to visit?","answer":"D","options":["It has the tallest buildings in Hangzhou.","It is the cheapest park to enter.","It is open only in the summer months.","It blends urban living with nature and marshland in one spot."],"explanation":"原文 ''brings together city life, nature and wetlands'' 的转述。"},{"q":"Why were the new buildings designed in a traditional way?","answer":"A","options":["So that they would blend into their natural surroundings.","To attract more shops to the area.","To make the park easier to guard.","Because traditional building was cheaper."],"explanation":"原文 ''… so that they would fit into the natural world around them'' 的转述。"},{"q":"Why is the wetland called the ''green lungs'' of the city?","answer":"B","options":["Because the trees there are painted green.","Because it cleans water and makes oxygen.","Because it is shaped like a pair of lungs.","Because only green plants may grow there."],"explanation":"原文 ''… cleans water and produces oxygen…'' 的转述。"}]'::jsonb, '[{"word":"bush","cn":"灌木"},{"word":"fashion","cn":"方式"},{"word":"lung","cn":"肺"}]'::jsonb, 2, 'elective1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Magical World at Disneyland', 'Of all the theme parks in the world, the one you are probably most familiar with is Disneyland, which can be found in several different countries. A visit to Disneyland brings you into a magical world and makes childhood dreams come true. Travelling through space, visiting a pirate ship, or meeting a lovely cartoon character are all possible here. As you wander around the fantasy park, you may suddenly see a famous character in a parade or even walking along the street. Of course, Disneyland also offers many exciting rides to amuse its guests, from enormous swinging ships to scary free-fall drops that turn your stomach over. There is something for almost every age and taste, so families with small children and groups of older friends can all find rides they love. If you want to have fun and a great deal more than fun, this is surely one park you should not miss.', '说明·迪士尼乐园主题公园', 154, '[{"q":"What does the writer say a visit to Disneyland feels like?","answer":"C","options":["Walking through a quiet history museum.","Taking a long and tiring mountain hike.","Entering a magical world where dreams come true.","Studying in a busy science classroom."],"explanation":"原文 ''brings you into a magical world and makes childhood dreams come true'' 的转述。"},{"q":"What might visitors see as they walk around the park?","answer":"D","options":["Wild reindeer feeding on the grass.","Workers building new roads everywhere.","Glaciers slowly melting in the sun.","Famous characters in a parade or on the street."],"explanation":"原文 ''… see a famous character in a parade or even walking along the street'' 的转述。"},{"q":"Why does the writer think the park suits many kinds of visitors?","answer":"A","options":["Because it offers rides suited to nearly all ages and tastes.","Because tickets there are completely free.","Because it is open all night long.","Because it is found in only one city."],"explanation":"原文 ''… something for almost every age and taste…'' 的转述。"}]'::jsonb, '[{"word":"pirate","cn":"海盗"},{"word":"wander","cn":"漫步"},{"word":"enormous","cn":"巨大的"},{"word":"swing","cn":"摆动"}]'::jsonb, 2, 'elective1', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Fun by the Sea at the Ocean Kingdom', 'In Zhuhai, China, the Ocean Kingdom is one of the leading sea-themed parks in the whole world. Here you can walk under a huge aquarium and watch up to twenty thousand fish swim above your head, including a whale shark many metres in length. Watching the dolphin and sea lion shows is both fun and educational, and you can also see all kinds of interesting animals, even real polar bears. The park has more rides than you can imagine: join a water fight against pirates, get turned upside down on an exciting roller coaster, or get soaked on one of the water rides. Then at night, a splendid parade of lights and a fireworks display fill the sky. If you grow hungry, the park has plenty of restaurants with tasty food for every appetite, and you can even eat while watching the fish swim by. If it is ocean entertainment you are looking for, this park has more than enough to keep you busy all day.', '说明·长隆海洋王国主题公园', 166, '[{"q":"What can visitors do under the huge aquarium?","answer":"B","options":["Ride a steam engine through a tunnel.","Look up at as many as twenty thousand fish swimming overhead.","Climb to the top of a glass tower.","Buy and cook their own seafood."],"explanation":"原文 ''watch up to twenty thousand fish swim above your head'' 的转述。"},{"q":"Which of these is offered as one of the park''s rides?","answer":"C","options":["A quiet boat tour of old villages.","A guided walk to see glaciers.","Joining a pretend battle with pirates in the water.","A class on making iron objects."],"explanation":"原文 ''join a water fight against pirates'' 的转述。"},{"q":"What does the park offer hungry visitors?","answer":"D","options":["Only a single small snack bar.","Food brought in from outside.","Free meals for all the children.","Plenty of eateries serving delicious meals to suit any appetite."],"explanation":"原文 ''plenty of restaurants with tasty food for every appetite'' 的转述。"}]'::jsonb, '[{"word":"polar","cn":"极地的"},{"word":"splendid","cn":"壮丽的"},{"word":"display","cn":"表演"},{"word":"entertainment","cn":"娱乐"}]'::jsonb, 2, 'elective1', 'U3');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'elective1', 'U3', 'A Night in the Wild', 'Last summer I camped alone in a (1)____ park far from any town. On the first morning, the wind hit the (2)____ of my tent and woke me up. When I looked out, the sun was already shining, but it was hard to tell (3)____ it was day or night. I walked to the (4)____ of the mountain and watched a river flow through the (5)____ below. Because there were no roads, getting there had been quite (6)____. My bag was heavy, since I had to (7)____ all my own food. The hike was full of sweat and hard work, yet I felt truly (8)____ to be in such a wild place. That evening I ate some sweet and (9)____ berries I found near my tent. Being there, alone under a wide sky, was the most (10)____ trip of my life.', 141, 2, '[{"q":"1","answer":"A","options":["remote","busy","noisy","modern"],"explanation":"remote park 偏远的公园。"},{"q":"2","answer":"B","options":["price","cloth","noise","machine"],"explanation":"the cloth of my tent 帐篷的布。"},{"q":"3","answer":"C","options":["because","although","whether","unless"],"explanation":"tell whether 分辨是否。"},{"q":"4","answer":"D","options":["price","noise","answer","edge"],"explanation":"the edge of the mountain 山的边缘。"},{"q":"5","answer":"A","options":["valley","city","shop","office"],"explanation":"the valley below 下方的山谷。"},{"q":"6","answer":"B","options":["cheap","difficult","loud","sweet"],"explanation":"quite difficult 相当困难。"},{"q":"7","answer":"C","options":["sell","hide","carry","throw"],"explanation":"carry all my food 携带所有食物。"},{"q":"8","answer":"D","options":["angry","bored","afraid","blessed"],"explanation":"feel blessed 感到有幸。"},{"q":"9","answer":"A","options":["sour","loud","tall","rich"],"explanation":"sweet and sour berries 又甜又酸的浆果。"},{"q":"10","answer":"B","options":["boring","rewarding","cheap","empty"],"explanation":"rewarding trip 值得的旅程。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'elective1', 'U3', 'A Visit to the Wetland Park', 'On Sunday my family visited a famous wetland park near our city. The park is huge, covering about ten square (1)____. As soon as we arrived, we took a boat (2)____ along the quiet water. Tall trees and green (3)____ grew on both sides, and colourful flowers were everywhere. Our guide said that the designers had tried hard to (4)____ the impact of people on the land. All the new buildings were made in a traditional (5)____ so that they would fit into nature. Many birds and fish make their (6)____ here, hidden among the reeds. Because the wetland (7)____ the water clean and produces fresh air, people call it the green (8)____ of the city. We (9)____ along the paths for hours, taking photos of everything we saw. It was a (10)____ day, and I learned a lot about how a park can protect nature.', 146, 2, '[{"q":"1","answer":"C","options":["hours","minutes","kilometres","seconds"],"explanation":"square kilometres 平方公里。"},{"q":"2","answer":"D","options":["song","price","rule","tour"],"explanation":"a boat tour 乘船游览。"},{"q":"3","answer":"A","options":["bushes","prices","noises","tickets"],"explanation":"trees and bushes 树木和灌木。"},{"q":"4","answer":"B","options":["sell","limit","raise","waste"],"explanation":"limit the impact 限制影响。"},{"q":"5","answer":"C","options":["price","noise","fashion","machine"],"explanation":"in a traditional fashion 以传统方式。"},{"q":"6","answer":"D","options":["price","noise","error","home"],"explanation":"make their home 安家。"},{"q":"7","answer":"A","options":["keeps","sells","breaks","loses"],"explanation":"keeps the water clean 保持水清洁。"},{"q":"8","answer":"B","options":["price","lungs","noise","shop"],"explanation":"the green lungs 绿肺。"},{"q":"9","answer":"C","options":["slept","shouted","wandered","drove"],"explanation":"wandered along the paths 沿小路漫步。"},{"q":"10","answer":"D","options":["boring","useless","empty","wonderful"],"explanation":"a wonderful day 美好的一天。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'elective1', 'U3', 'Rules of the Wildlife Reserve', 'A wildlife reserve is set up to (1)____ the rare animals that live inside it. To keep the land in its natural (2)____, the reserve has several strict rules. First, all hunting is (3)____, so that the animals can live and grow in peace. Second, no new buildings may go up within the park''s (4)____. Third, visitors must follow the marked (5)____ and never wander off into the wild on their own. These rules may seem hard, but they work. Years ago, only a few wild tigers were left in this (6)____. After a (7)____ on development was put in place, their numbers slowly began to (8)____. Now the reserve is home to many tigers and (9)____. Large cats like these need (10)____ spaces to hunt for food, and a big, well-protected park gives them exactly that.', 137, 2, '[{"q":"1","answer":"A","options":["protect","sell","harm","forget"],"explanation":"protect the animals 保护动物。"},{"q":"2","answer":"B","options":["price","state","noise","shop"],"explanation":"natural state 自然状态。"},{"q":"3","answer":"C","options":["sold","begun","banned","lost"],"explanation":"hunting is banned 狩猎被禁止。"},{"q":"4","answer":"D","options":["songs","prices","noises","boundaries"],"explanation":"within the boundaries 在边界内。"},{"q":"5","answer":"A","options":["routes","prices","noises","errors"],"explanation":"marked routes 标好的路线。"},{"q":"6","answer":"B","options":["price","region","noise","song"],"explanation":"in this region 在这一地区。"},{"q":"7","answer":"C","options":["song","price","ban","noise"],"explanation":"a ban on development 发展禁令。"},{"q":"8","answer":"D","options":["fall","drop","stop","rise"],"explanation":"began to rise 开始回升。"},{"q":"9","answer":"A","options":["leopards","prices","machines","tickets"],"explanation":"tigers and leopards 虎和豹。"},{"q":"10","answer":"B","options":["cheap","wide","loud","sour"],"explanation":"wide spaces 广阔的空间。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'elective1', 'U3', 'A Day at the Theme Park', 'My cousin and I spent a whole day at a famous (1)____ park last weekend. There were rides for almost every (2)____ and taste, so we never got bored. First we tried an (3)____ swinging ship that lifted us high into the air. Then we got turned upside (4)____ on a fast roller coaster, screaming the whole way. As we (5)____ around the park, we saw a parade of cartoon characters walking down the (6)____. In the afternoon we joined a water fight against (7)____ and got completely wet. When we grew hungry, we found a restaurant with tasty (8)____ for every appetite. At night, a (9)____ display of fireworks lit up the sky above us. It was an (10)____ day full of fun, and we both agreed we would come back again soon.', 134, 2, '[{"q":"1","answer":"C","options":["price","noise","theme","rule"],"explanation":"theme park 主题公园。"},{"q":"2","answer":"D","options":["price","noise","shop","age"],"explanation":"every age and taste 各个年龄和口味。"},{"q":"3","answer":"A","options":["enormous","empty","quiet","cheap"],"explanation":"an enormous swinging ship 巨大的摇摆船。"},{"q":"4","answer":"B","options":["in","down","off","up"],"explanation":"upside down 颠倒。"},{"q":"5","answer":"C","options":["slept","drove","wandered","cried"],"explanation":"wandered around 四处漫步。"},{"q":"6","answer":"D","options":["price","noise","error","street"],"explanation":"down the street 沿街道。"},{"q":"7","answer":"A","options":["pirates","songs","prices","tickets"],"explanation":"fight against pirates 对抗海盗。"},{"q":"8","answer":"B","options":["noise","food","price","error"],"explanation":"tasty food 美味的食物。"},{"q":"9","answer":"C","options":["boring","quiet","splendid","cheap"],"explanation":"a splendid display 壮丽的表演。"},{"q":"10","answer":"D","options":["empty","boring","useless","exciting"],"explanation":"an exciting day 激动人心的一天。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'elective1', 'U3', 'Designing My Ideal Park', 'In art class our teacher asked us to (1)____ an ideal park of our own. I started by drawing a (2)____ of the whole park, marking where everything would be. Near the gate I placed a beautiful (3)____ that would shoot water high into the air. Visitors could rent a (4)____ boat and row across a quiet lake. For families with children, there would be gentle rides and a place to look at (5)____. To protect nature, I decided that no new building could go up outside the marked (6)____, and that hunting would be strictly (7)____. Trees and bushes would grow everywhere, making the air fresh and (8)____. I also planned a long underwater (9)____ where people could walk and watch the fish swim past. When I finished, my teacher said my park was (10)____ and full of clever ideas.', 141, 2, '[{"q":"1","answer":"A","options":["design","sell","hide","lose"],"explanation":"design a park 设计一座公园。"},{"q":"2","answer":"B","options":["price","map","noise","shop"],"explanation":"a map 一张地图。"},{"q":"3","answer":"C","options":["price","noise","fountain","error"],"explanation":"a beautiful fountain 美丽的喷泉。"},{"q":"4","answer":"D","options":["song","price","noise","pedal"],"explanation":"a pedal boat 脚踏船。"},{"q":"5","answer":"A","options":["flowers","prices","noises","errors"],"explanation":"look at flowers 观赏花朵。"},{"q":"6","answer":"B","options":["prices","boundaries","noises","songs"],"explanation":"the marked boundaries 标好的边界。"},{"q":"7","answer":"C","options":["sold","begun","prohibited","lost"],"explanation":"hunting prohibited 禁止狩猎。"},{"q":"8","answer":"D","options":["loud","sour","rich","clean"],"explanation":"fresh and clean 清新洁净。"},{"q":"9","answer":"A","options":["corridor","price","noise","error"],"explanation":"an underwater corridor 水下走廊。"},{"q":"10","answer":"B","options":["boring","incredible","useless","empty"],"explanation":"incredible 令人惊叹。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'elective1', 'U3', 'A Park That Celebrates Culture', 'Deep in the green mountains of the south stands a special theme park that (1)____ the region''s old culture. Famous country music groups (2)____ on performances there all year round, both indoors and out. People travel from far away to watch skilled workers make wood, glass and (3)____ objects in the old-fashioned way. Visiting the candy shop and tasting sweets made the same way as a hundred and fifty years ago is a truly (4)____ experience. Riding the only (5)____ engine still working in the area is a special treat, as it carries you slowly through the hills. For those who love rides, the park has a (6)____ old wooden roller coaster, famous for its long track. As you (7)____ from one corner to another, you feel as if you have stepped back in (8)____. Every show and ride helps you (9)____ the history of this place. Come here to have fun while learning about a (10)____ way of life.', 160, 2, '[{"q":"1","answer":"C","options":["sells","hides","celebrates","forgets"],"explanation":"celebrates the culture 颂扬文化。"},{"q":"2","answer":"D","options":["take","give","make","put"],"explanation":"put on performances 举办表演。"},{"q":"3","answer":"A","options":["iron","price","noise","error"],"explanation":"iron objects 铁器。"},{"q":"4","answer":"B","options":["loud","rare","sour","empty"],"explanation":"a rare experience 难得的经历。"},{"q":"5","answer":"C","options":["price","noise","steam","song"],"explanation":"steam engine 蒸汽机车。"},{"q":"6","answer":"D","options":["boring","useless","cheap","superb"],"explanation":"a superb roller coaster 极佳的过山车。"},{"q":"7","answer":"A","options":["wander","sleep","sell","lose"],"explanation":"wander from corner to corner 四处漫步。"},{"q":"8","answer":"B","options":["price","time","noise","shop"],"explanation":"step back in time 时光倒流。"},{"q":"9","answer":"C","options":["forget","waste","understand","lose"],"explanation":"understand the history 了解历史。"},{"q":"10","answer":"D","options":["boring","useless","empty","traditional"],"explanation":"a traditional way of life 传统的生活方式。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·对话 Finding the Way in the Park', '选择性必修一 U3 · dialogue', 3, 'Jake: Excuse me, do you happen to know where the fountain is?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·短文 A Park with No Roads', '选择性必修一 U3 · passage', 2, 'In the far north of Sweden lies a vast park with no roads and no towns.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·对话 Planning a Trip to the Theme Park', '选择性必修一 U3 · dialogue', 3, 'Yuhui: Let''s plan our day at the theme park tomorrow.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·短文 The Green Lungs of the City', '选择性必修一 U3 · passage', 2, 'Our city''s wetland park is a green, watery world full of life.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·对话 Asking for Directions', '选择性必修一 U3 · dialogue', 3, 'Tourist: Pardon me, how do I get to the underwater corridor?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U3 听力·短文 Tips for Visiting a Park', '选择性必修一 U3 · passage', 2, 'Here are a few simple tips for visiting a national park.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write an Introduction to a Park(写一篇公园介绍)', 'An Introduction to a Park', '假设你叫李华,学校英语公众号正在征集''我最喜欢的公园''介绍。请用英语写一篇约80词的短文,介绍或推荐一座你喜欢的公园(可以是国家公园、湿地公园或主题公园),内容包括:① 公园的名称和地点;② 园里有什么看点或可以做的活动(至少两点);③ 你推荐它的理由。注意:用说明文语气,信息清楚、句子地道。', 'Suppose you are Li Hua. Your school''s English page is collecting introductions to ''My Favourite Park''. Write a short passage (about 80 words) to introduce or recommend a park you like (a national park, a wetland park, or a theme park), including: 1) its name and location; 2) at least two attractions or activities there; 3) why you recommend it.', '["公园名称与地点(… is a … park in …)","看点 / 活动(至少两点)(There you can … / It is famous for …)","推荐理由(I recommend it because … / If you … , don''t miss it.)","说明文语气、信息清楚、句子地道"]'::jsonb, 70, 100, 'If you love nature, I strongly recommend Xixi Wetland Park in the west of Hangzhou. It is the first national wetland park in China and covers a vast area of water, trees and colourful flowers. There you can take a boat tour along the quiet paths, watch all kinds of birds, and learn about the customs of the old villages. Because it cleans the water and produces fresh air, people call it the green lungs of the city. It is a peaceful and beautiful place, so don''t miss it when you visit Hangzhou!', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["If you love nature, I strongly recommend Xixi Wetland Park in the west of Hangzhou.","There you can take a boat tour, watch all kinds of birds, and learn about the old villages.","Because it cleans the water and produces fresh air, people call it the green lungs of the city.","It is a peaceful and beautiful place, so don''t miss it when you visit Hangzhou!"]'::jsonb, '[{"wrong":"It is famous of its beautiful lake.","correct":"It is famous for its beautiful lake.","note":"be famous for sth 因某事出名,介词用 for。"},{"wrong":"There you can saw many birds.","correct":"There you can see many birds.","note":"情态动词 can 后用动词原形 see。"},{"wrong":"What makes the park special are its clean water.","correct":"What makes the park special is its clean water.","note":"what 引导的主语从句作主语,谓语用单数 is。"}]'::jsonb, '【公园介绍结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'elective1', 'U3', '{"title":"主语从句(Subject Clauses)速查","intro":"主语从句就是用一个句子来作整句的主语。判断口诀:从句完整、不缺主宾 → that;从句缺主语/宾语 → what / who;表''是否'' → whether(句首不用 if);怕句子头重脚轻,就用 it 作形式主语,把从句挪到句末。","table":{"headers":["引导词","用法 / 例句"],"rows":[["that","从句完整、只起连接、不充当成分:That he came late is true."],["what / who","从句缺主语或宾语,该词在从句里充当成分:What matters is safety."],["whether","表''是否'',句首主语从句只能用 whether:Whether we go depends on the weather."],["why / how / where","表原因/方式/地点,从句缺该状语:Why he left is unknown."],["it 作形式主语","It is important that we protect parks.（真正主语 that 从句后置)"]]},"specialRules":[{"rule":"that 在主语从句中不充当成分,只起连接,且句首一般不能省略","mark":"That she won surprised us.（that 不能省)"},{"rule":"句首主语从句表''是否''用 whether,绝不用 if","mark":"Whether it rains matters. √ / If it rains matters. ×"},{"rule":"what / who 在从句里充当主语或宾语,不可换成 that","mark":"What he said(said 缺宾语)→ what,不能用 that"},{"rule":"it 作形式主语,真正的从句移到句末,it 后多接 that / whether / who","mark":"It is unknown whether he will come."}],"why":["主语从句很长时,句子会''头重脚轻'',所以常用 it 占住主语位置、把真正的从句放到后面,读起来更顺。引导词选 that 还是 what/who,关键看从句本身缺不缺主语或宾语。"],"gaokaoPoints":["that 与 what 的区分(从句缺不缺成分);whether 与 if 的区分(主语从句句首只用 whether);语法填空高频。","it 作形式主语句型:It is + 形容词/名词 + that 从句;以及 It doesn''t matter who/whether…。"],"examVsReal":[{"exam":"That he passed the test made us happy.（考试/书面)","real":"We were happy (that) he passed the test.","note":"口语里常把长主语从句换成 it 句型或直接换说法,少用句首 that 从句"},{"exam":"Whether they will come is still unknown.（考试)","real":"We don''t know if they''ll come.","note":"考试句首用 whether;口语在宾语位置常用 if,更口语化"}]}'::jsonb);
